mapper.select:
SELECT r.user_id FROM kb_knowledge_gap_event_recipient r JOIN kb_knowledge_gap_event e ON e.event_id = r.event_id
WHERE r.event_id = #{eventId} AND r.user_id > #{afterUserId} AND r.user_id <> e.actor_user_id
ORDER BY r.user_id LIMIT #{limit}

mapper.update:
UPDATE kb_knowledge_gap_notification_projection
SET recipient_cursor = #{cursor}, lease_until = now() + make_interval(secs => #{leaseSeconds}), updated_at = now()
WHERE event_id = #{eventId} AND lease_owner = #{owner} AND claim_token = #{token}
    AND status = 'PENDING' AND recipient_cursor < #{cursor}
